reference_solution:
def paint_fence_ways(n, k):
    if n == 1:
        return k
    two_back, one_back = k, k * k
    for _ in range(3, n + 1):
        two_back, one_back = one_back, (one_back + two_back) * (k - 1)
    return one_back

